beforeExample:
public class MyClass {
    void foo(int a, int b) {
        if (a > 0 && b == b && a < 10) {
            System.out.println("Condition met");
        }
    }
}

afterExample:
public class MyClass {
    void foo(int a, int b) {
        if (a > 0 && true && a < 10) {
            System.out.println("Condition met");
        }
    }
}

